package org.olcbox.app.data.importer

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Regression for a real base64 subscription whose links use the `host:port/?query` form (a slash
 * before the query). The trailing slash used to break host:port parsing, so only the single server
 * WITHOUT a slash imported. All 25 share links must now parse.
 */
class RealSubscriptionParseTest {
    private val blob = ""

    @Test
    fun slashBeforeQueryDoesNotDropServers() {
        val profiles = ShareLinkParser.parseSubscription(blob)
        assertTrue(profiles.size >= 24, "expected all servers, got ${profiles.size}")
        assertTrue(profiles.any { it.server == "45.145.40.22" })
        assertTrue(profiles.any { it.server == "151.240.151.202" })
    }

    @Test
    fun splitHostPortIgnoresTrailingPath() {
        assertEquals("1.2.3.4" to 443, UriCodec.splitHostPort("1.2.3.4:443/?type=tcp"))
        assertEquals("1.2.3.4" to 443, UriCodec.splitHostPort("1.2.3.4:443/"))
        assertEquals("a.com" to 8443, UriCodec.splitHostPort("a.com:8443"))
        assertEquals("2001:db8::1" to 443, UriCodec.splitHostPort("[2001:db8::1]:443/path"))
    }
}
